import { ResponseError } from "../../errors.js";
import { Writer } from "../../protocol/writer.js";
import { createAPI } from "../definitions.js";
/*
  DeleteTopics Request (Version: 4) => [topic_names] timeout_ms TAG_BUFFER
    topic_names => COMPACT_STRING
    timeout_ms => INT32

  Note that topic_names is an array of plain strings, not of structs: it only becomes
  [topics] with per entry tagged fields in v6. Appending a tagged field section after each
  name makes the broker drop the connection.
*/
export function createRequest(topics, timeoutMs) {
    return Writer.create().appendArray(topics, (w, topic) => w.appendString(topic.name ?? ''), true, false).appendInt32(timeoutMs).appendTaggedFields();
}
/*
  DeleteTopics Response (Version: 4) => throttle_time_ms [responses] TAG_BUFFER
    throttle_time_ms => INT32
    responses => name error_code TAG_BUFFER
      name => COMPACT_STRING
      error_code => INT16
*/
export function parseResponse(_correlationId, apiKey, apiVersion, reader) {
    const errors = [];
    const response = {
        throttleTimeMs: reader.readInt32(),
        responses: reader.readArray((r, i) => {
            const topicResponse = { name: r.readString(), topicId: '00000000-0000-0000-0000-000000000000', errorCode: r.readInt16(), errorMessage: null };
            if (topicResponse.errorCode !== 0) {
                errors.push([`/responses/${i}`, [topicResponse.errorCode, topicResponse.errorMessage]]);
            }
            return topicResponse;
        })
    };
    reader.readTaggedFields();
    if (errors.length) {
        throw new ResponseError(apiKey, apiVersion, Object.fromEntries(errors), response);
    }
    return response;
}
export const api = createAPI(20, 4, createRequest, parseResponse);
